using System.ComponentModel.DataAnnotations; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.AspNetCore.Mvc.RazorPages; using Tanda.Domain.Abstractions; using Tanda.Domain.Entities;
namespace Tanda.Web.Pages.Catalog.Capacity;
[Authorize(Roles="Administrator")] public class IndexModel(IDailyCapacityRepository capacities,IBusinessParameters parameters):PageModel{public IReadOnlyList<Day> Days{get;private set;}=[];[BindProperty]public InputModel Input{get;set;}=new();public class Day{public DateOnly Date{get;init;}public int Total{get;init;}public int Committed{get;init;}}public class InputModel{[Required(ErrorMessage="La fecha es requerida.")]public DateOnly Date{get;set;}[Required(ErrorMessage="El esfuerzo total es requerido.")][Range(1,100000,ErrorMessage="El esfuerzo debe ser mayor que cero.")]public int TotalEsfuerzo{get;set;}}public async Task OnGetAsync(CancellationToken ct){await LoadAsync(ct);}public async Task<IActionResult> OnPostAsync(CancellationToken ct){var current=await capacities.GetByDateAsync(Input.Date,ct);if(!ModelState.IsValid){await LoadAsync(ct);return Page();}if(current is not null&&Input.TotalEsfuerzo<current.CommittedEsfuerzo){ModelState.AddModelError("Input.TotalEsfuerzo",$"El total no puede ser menor al esfuerzo ya comprometido ({current.CommittedEsfuerzo}).");await LoadAsync(ct);return Page();}await capacities.UpsertAsync(Input.Date,Input.TotalEsfuerzo,ct);TempData["Message"]="Capacidad guardada correctamente.";return RedirectToPage();}private async Task LoadAsync(CancellationToken ct){var from=DateOnly.FromDateTime(DateTime.Today);var records=await capacities.GetRangeAsync(from,from.AddDays(59),ct);var lookup=records.ToDictionary(x=>x.Date);Days=Enumerable.Range(0,60).Select(i=>{var date=from.AddDays(i);return lookup.TryGetValue(date,out var x)?new Day{Date=date,Total=x.TotalEsfuerzo,Committed=x.CommittedEsfuerzo}:new Day{Date=date,Total=parameters.DefaultDailyCapacity,Committed=0};}).ToList();}}
